    # Doc 06 §2.8 : append-only. Aucun UPDATE/DELETE en app ; le trigger rend
    # la propriété vérifiable au niveau base. Le rollover d'archive système
    # (ENF-701) devra lever ce verrou explicitement (décision Sprint 4).
    op.execute(
        "CREATE FUNCTION audit_log_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ "
        "BEGIN "
        "RAISE USING MESSAGE = 'audit_log is append-only: ' || TG_OP || ' forbidden', "
        "ERRCODE = 'restrict_violation'; "
        "END $$"
    )
    op.execute(
        "CREATE TRIGGER trg_audit_log_append_only "
        "BEFORE UPDATE OR DELETE ON audit_log "
        "FOR EACH ROW EXECUTE FUNCTION audit_log_append_only()"
    )
